import { chromium } from "playwright";
import fs from "fs";

async function test() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });

  const html = `
    <!DOCTYPE html>
    <html>
    <head>
      <style>
        body { background: #07070c; color: #fff; font-family: sans-serif; padding: 40px; }
        .work-samples-list { max-width: 1200px; margin: 0 auto; display: flex; flex-direction: column; gap: 40px; }
        .work-project-row {
          display: grid;
          grid-template-columns: 560px 1fr;
          gap: 32px;
          background: rgba(18,18,28,0.7);
          border: 1px solid rgba(255,255,255,0.08);
          border-radius: 24px;
          padding: 24px;
          align-items: center;
        }
        .w-img {
          container-type: size;
          position: relative;
          width: 100%;
          aspect-ratio: 16/10;
          border-radius: 20px;
          overflow: hidden;
          background: #0d0e17;
          border: 1px solid rgba(255,255,255,0.1);
        }
        .w-img .live-preview-image {
          position: absolute;
          top: 0;
          left: 0;
          width: 100%;
          height: auto;
          min-height: 100%;
          display: block;
          object-fit: cover;
          object-position: top center;
          transform: translateY(0);
          transition: transform 0.6s cubic-bezier(0.25, 1, 0.5, 1);
          will-change: transform;
        }
        .work-project-row:hover .w-img .live-preview-image,
        .w-img:hover .live-preview-image,
        .w-img.is-scrolling .live-preview-image {
          transform: translateY(min(0px, calc(-100% + 100cqh)));
          transition: transform 10s linear;
        }
        .live-preview-link {
          position: absolute;
          inset: 0;
          z-index: 4;
          text-indent: -9999px;
        }
        .w-img::after {
          content: "Open live website ↗";
          position: absolute;
          left: 14px;
          bottom: 14px;
          z-index: 5;
          padding: 7px 14px;
          border-radius: 999px;
          background: rgba(5,5,8,0.85);
          border: 1px solid rgba(255,255,255,0.25);
          color: #fff;
          font-size: 11px;
          font-weight: 700;
          letter-spacing: 0.05em;
          text-transform: uppercase;
          backdrop-filter: blur(8px);
          pointer-events: none;
        }
        .work-project-body h3 { font-size: 28px; margin: 0 0 12px; }
        .work-project-body p { color: #a1a1aa; line-height: 1.6; }
      </style>
    </head>
    <body>
      <div class="work-samples-list">
        <article class="work-project-row" id="row-humanxt">
          <div class="w-img" id="wimg-humanxt">
            <img class="live-preview-image" id="img-humanxt" src="data:image/webp;base64," alt="HumanXT" />
            <a class="live-preview-link" href="https://humanxt.com/" target="_blank">Open HumanXT live website</a>
          </div>
          <div class="work-project-body">
            <h3>HumanXT</h3>
            <p>Revamp for CXOs and HR leaders.</p>
          </div>
        </article>

        <article class="work-project-row" id="row-weavings">
          <div class="w-img" id="wimg-weavings">
            <img class="live-preview-image" id="img-weavings" src="data:image/webp;base64," alt="Weavings" />
            <a class="live-preview-link" href="https://www.weavings.in/" target="_blank">Open Weavings live website</a>
          </div>
          <div class="work-project-body">
            <h3>Weavings</h3>
            <p>Staffing & Manpower solutions.</p>
          </div>
        </article>

        <article class="work-project-row" id="row-betterceasons">
          <div class="w-img" id="wimg-betterceasons">
            <img class="live-preview-image" id="img-betterceasons" src="data:image/webp;base64," alt="Better Ceasons" />
            <a class="live-preview-link" href="https://betterceasons.com/" target="_blank">Open Better Ceasons live website</a>
          </div>
          <div class="work-project-body">
            <h3>Better Ceasons</h3>
            <p>Clean technology vision and platform.</p>
          </div>
        </article>
      </div>
    </body>
    </html>
  `;

  // Serve or set content with base url
  await page.setContent(html, { waitUntil: "load" });

  // Check initial state
  const initialRect = await page.evaluate(() => {
    const img = document.getElementById("img-humanxt");
    const box = document.getElementById("wimg-humanxt");
    const ir = img.getBoundingClientRect();
    const br = box.getBoundingClientRect();
    return { topDiff: ir.top - br.top, irH: ir.height, brH: br.height };
  });
  console.log("Initial state HumanXT:", initialRect);

  // Hover over row-humanxt
  await page.hover("#row-humanxt");
  await page.waitForTimeout(3000); // 3s into 10s scroll

  const midScrollRect = await page.evaluate(() => {
    const img = document.getElementById("img-humanxt");
    const box = document.getElementById("wimg-humanxt");
    const ir = img.getBoundingClientRect();
    const br = box.getBoundingClientRect();
    return { topDiff: ir.top - br.top, scrolledPx: Math.abs(ir.top - br.top) };
  });
  console.log("Mid-scroll (3s) HumanXT:", midScrollRect);

  // Take screenshot of mid-scroll
  await page.screenshot({ path: "scripts/test-mid-scroll-humanxt.png" });

  // Move away
  await page.mouse.move(0, 0);
  await page.waitForTimeout(1000); // return to top

  const resetRect = await page.evaluate(() => {
    const img = document.getElementById("img-humanxt");
    const box = document.getElementById("wimg-humanxt");
    const ir = img.getBoundingClientRect();
    const br = box.getBoundingClientRect();
    return { topDiff: ir.top - br.top };
  });
  console.log("Reset state HumanXT:", resetRect);

  await browser.close();
}

test().catch(console.error);
